# -*- coding: utf-8 -*-
"""
Script tu dong ghi de data_pipeline/filter_restaurants.py voi encoding UTF-8 chuan.
Dung base64 de tranh MOI van de mojibake/encoding khi copy-paste qua Windows.

Chay: python fix_filter_restaurants.py
(chay dung trong thu muc goc project, noi co thu muc data_pipeline)
"""
import base64
from pathlib import Path

B64_CONTENT = ""

def main():
    target = Path("data_pipeline/filter_restaurants.py")
    if not target.parent.exists():
        print("LOI: khong tim thay thu muc data_pipeline. Hay chay script tu thu muc goc project.")
        return

    raw_bytes = base64.b64decode(B64_CONTENT)
    text = raw_bytes.decode("utf-8")

    with open(target, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)

    print(f"Da ghi de thanh cong: {target}")

    # Tu kiem tra lai ngay sau khi ghi
    with open(target, "r", encoding="utf-8") as f:
        check_content = f.read()

    checks = [
        ("def _flatten_field" in check_content, "co dinh nghia ham _flatten_field"),
        ("nhà hàng" in check_content, "tu khoa tieng Viet dung encoding (nha hang)"),
        (check_content.count("_flatten_field") == 6, "du 6 lan xuat hien _flatten_field"),
    ]
    all_ok = True
    for ok, desc in checks:
        status = "OK" if ok else "LOI"
        print(f"  [{status}] {desc}")
        if not ok:
            all_ok = False

    if all_ok:
        print()
        print("=== THANH CONG: file da dung 100%, co the git add/commit/push ngay ===")
    else:
        print()
        print("=== VAN CON LOI - lien he lai de kiem tra them ===")

if __name__ == "__main__":
    main()
